  uint32_t svc_sp;
  uint32_t svc_lr;
  uint32_t abt_spsr;
  uint32_t abt_sp;
  uint32_t abt_lr;
  uint32_t und_spsr;
  uint32_t und_sp;
  uint32_t und_lr;
  uint32_t pmcr;
};

struct arm_sm_nsec_ctx
{
  struct arm_sm_banked_regs regs;

  uint32_t r8;
  uint32_t r9;
  uint32_t r10;
  uint32_t r11;
  uint32_t r12;

  uint32_t r0;
  uint32_t r1;
  uint32_t r2;
  uint32_t r3;
  uint32_t r4;
  uint32_t r5;
  uint32_t r6;
  uint32_t r7;

  /* Return state */

  uint32_t mon_lr;
  uint32_t mon_spsr;
};

struct arm_sm_sec_ctx
{
  struct arm_sm_banked_regs regs;

  uint32_t r0;
  uint32_t r1;
  uint32_t r2;
  uint32_t r3;
  uint32_t r4;
  uint32_t r5;
  uint32_t r6;
  uint32_t r7;

  /* Return state */

  uint32_t mon_lr;
  uint32_t mon_spsr;
};

struct arm_sm_ctx
{
  struct arm_sm_sec_ctx sec;
  struct arm_sm_nsec_ctx nsec;
};

