    }

    DMSG("TEE_CreatePersistentObject(%s) in TEE_STORAGE_PRIVATE(0x%08" PRIx32 ")...\n", name1, (uint32_t)TEE_STORAGE_PRIVATE);
    res = TEE_CreatePersistentObject(TEE_STORAGE_PRIVATE,
