    case TA_HELLO_WORLD_CMD_DEC_VALUE:
        // return dec_value(param_types, params);
        return TEE_SUCCESS;
    default:
        EMSG("unknown cmd: 0x%08" PRIx32 "\n", cmd_id);
        return TEE_ERROR_BAD_PARAMETERS;
    }
}

